def comps_debug(grid):
 divider=next(r for r,row in enumerate(grid) if all(v==5 for v in row))
 cells={(r,c) for r in range(divider) for c in range(len(grid[0])) if grid[r][c] not in (0,5)}
 def comp(cells):
  rem=set(cells); out=[]
  while rem:
   seed=rem.pop(); x={seed}; st=[seed]
   while st:
    r,c=st.pop()
    for n in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
     if n in rem: rem.remove(n); x.add(n); st.append(n)
   out.append(x)
  return out
 return [(len(x),min(r for r,c in x),min(c for r,c in x),max(c for r,c in x)) for x in comp(cells)]
